import { Song } from "../synth/synth";
import { HTML } from "imperative-html/dist/esm/elements-strict";
import { SongDocument } from "./SongDocument";
import { Prompt } from "./Prompt";
import { generateUid } from "./SongRecovery";
import { ChangeSongTitle } from "./changes";
import { StoredSong, getAllSongs, getSong, saveSong, deleteSong } from "./SongStorage";
import { ColorConfig } from "./ColorConfig";

	const {button, div, h2, p, input} = HTML;

export class SongLibraryPrompt implements Prompt {
	private readonly _filterInput: HTMLInputElement = input({type: "text", style: "width: 100%; box-sizing: border-box;", placeholder: "Filter by name..."});
	private readonly _songContainer: HTMLDivElement = div({style: "max-height: 385px; overflow-y: auto;"});
	private readonly _cancelButton: HTMLButtonElement = button({class: "cancelButton"});

	private _songs: StoredSong[] = [];
	private _filter: string = "";

	public readonly container: HTMLDivElement = div({class: "prompt noSelection", style: "width: 400px;"},
		h2("Song Library"),
		p("Songs are auto-saved in this browser as you edit them."),
		div({style: "margin-bottom: 0.5em;"}, this._filterInput),
		this._songContainer,
		this._cancelButton,
	);

	constructor(private _doc: SongDocument) {
		this._cancelButton.addEventListener("click", this._close);
		this._filterInput.addEventListener("input", this._whenFilterChanged);
		this._refresh();
	}

	public cleanUp = (): void => {
		this._cancelButton.removeEventListener("click", this._close);
		this._filterInput.removeEventListener("input", this._whenFilterChanged);
	}

	private _close = (): void => {
		this._doc.undo();
	}

	private _whenFilterChanged = (): void => {
		this._filter = this._filterInput.value.trim().toLowerCase();
		this._renderList();
	}

	private _refresh(): void {
		getAllSongs().then(songs => {
			this._songs = songs;
			this._renderList();
		});
	}

	private _renderList(): void {
		this._songContainer.innerHTML = "";

		if (this._songs.length == 0) {
			this._songContainer.appendChild(p("There are no saved songs yet. Songs are saved automatically as you edit them."));
			return;
		}

		const songs = this._songs.filter(song => this._filter == "" || song.name.toLowerCase().indexOf(this._filter) != -1);

		if (songs.length == 0) {
			this._songContainer.appendChild(p("No songs match this filter."));
			return;
		}

		for (const song of songs) {
			this._songContainer.appendChild(this._buildRow(song));
		}
	}

	private _buildRow(song: StoredSong): HTMLElement {
		const isCurrent: boolean = (song.uid == this._doc.libraryUid);

		const nameInput: HTMLInputElement = input({value: song.name, style: "flex-grow: 1; min-width: 6em;", maxlength: "30", title: song.name + "\nModified: " + new Date(song.updatedAt).toLocaleString()});
		nameInput.addEventListener("change", () => { this._renameSong(song, nameInput.value); });

		const openButton: HTMLButtonElement = button({class: "last-button", style: "flex-shrink: 0;"}, isCurrent ? "Reload" : "Open");
		openButton.addEventListener("click", () => { this._openSong(song, false); });

		const newTabButton: HTMLButtonElement = button({class: "last-button", style: "flex-shrink: 0;"}, "New Tab");
		newTabButton.addEventListener("click", () => { this._openSong(song, true); });

		const copyButton: HTMLButtonElement = button({class: "last-button", style: "flex-shrink: 0;", title: "Copy song link"}, "URL");
		copyButton.addEventListener("click", () => { this._copySongUrl(song); });

		const duplicateButton: HTMLButtonElement = button({class: "last-button", style: "flex-shrink: 0;", title: "Duplicate song"}, "⧉");
		duplicateButton.addEventListener("click", () => { this._duplicateSong(song); });

		const deleteButton: HTMLButtonElement = button({class: "last-button", style: "flex-shrink: 0;", title: "Delete song"}, "🗑");
		deleteButton.addEventListener("click", () => { this._deleteSong(song); });

		const row: HTMLDivElement = div({style: "display: flex; flex-direction: column; margin: 3px 0; padding: 4px; background: " + ColorConfig.uiWidgetBackground + ";"},
			div({style: "display: flex; align-items: center; gap: 4px;"},
				nameInput,
			),
			div({style: `display: flex; align-items: center; gap: 4px; margin-top: 3px; color: ${ColorConfig.secondaryText}; font-size: smaller;`},
				div({style: "flex-grow: 1;"},
					new Date(song.updatedAt).toLocaleString() + " · " + (song.data.length >= 1024 ? (song.data.length / 1024).toFixed(1) + " KB" : song.data.length + " B"),
				),
				openButton, newTabButton, copyButton, duplicateButton, deleteButton,
			),
		);
		return row;
	}

	private _renameSong(song: StoredSong, newName: string): void {
		newName = newName.trim();
		if (newName == "" || newName == song.name) {
			this._refresh();
			return;
		}
		if (song.uid == this._doc.libraryUid) {
			// Renaming the currently open song: change its title normally so that
			// the song data and the library stay in sync.
			new ChangeSongTitle(this._doc, song.name, newName);
		} else {
			// Renaming a song that isn't open: rewrite its title in the song data.
			try {
				const parsed: Song = new Song(song.data);
				parsed.title = newName;
				song.data = parsed.toBase64String();
			} catch (error) {
				console.warn("Could not rename song:", error);
			}
			song.name = newName;
			song.updatedAt = Date.now();
			saveSong(song);
		}
		this._refresh();
	}

	private _openSong(song: StoredSong, newTab: boolean): void {
		const url: string = new URL("#" + song.data, location.href).href;
		if (newTab) {
			window.open(url, "_blank");
		} else {
			this._doc.prompt = null;
			location.hash = "#" + song.data;
		}
	}

	private _copySongUrl(song: StoredSong): void {
		const url: string = new URL("#" + song.data, location.href).href;
		const tryClipboard = (): void => {
			if (navigator.clipboard != undefined) {
				navigator.clipboard.writeText(url).catch(() => { window.prompt("Copy song link:", url); });
			} else {
				window.prompt("Copy song link:", url);
			}
		};
		tryClipboard();
	}

	private _duplicateSong(song: StoredSong): void {
		const now: number = Date.now();
		saveSong({ uid: generateUid(), name: song.name + " (copy)", data: song.data, createdAt: now, updatedAt: now });
		this._refresh();
	}

	private _deleteSong(song: StoredSong): void {
		if (!window.confirm("Delete \"" + song.name + "\" from the library? This cannot be undone.")) return;
		deleteSong(song.uid);
		this._refresh();
	}
}

